// huge-200k.js — 200,000 lines of plausible JavaScript: classes, arrow functions, template
// literals, async/await, destructuring, regex literals, JSDoc and ordinary comments.
'use strict';

/** A bucket with an identity, a payload and a few derived facts. Block 1. */
export class Bucket1 {
  #weight = 28.7;
  tags = ['bucket', 'block-1'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Bucket1(this.id, this.name);
    copy.#weight = this.#weight * factor; // 2x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/bucket/${encodeURIComponent('1')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Bucket1(id, name);
  }
}

export const findBucket1 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
const bucketPattern1 = /^bucket-(\d+)$/i;

