const anchorPattern684 = /^anchor-(\d+)$/i;

/** A bucket with an identity, a payload and a few derived facts. Block 685. */
export class Bucket685 {
  #weight = 81.5;
  tags = ['bucket', 'block-685'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Bucket685(this.id, this.name);
    copy.#weight = this.#weight * factor; // 5x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/bucket/${encodeURIComponent('685')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Bucket685(id, name);
  }
}

