const signalPattern1122 = /^signal-(\d+)$/i;

/** A bucket with an identity, a payload and a few derived facts. Block 1123. */
export class Bucket1123 {
  #weight = 34.2;
  tags = ['bucket', 'block-1123'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Bucket1123(this.id, this.name);
    copy.#weight = this.#weight * factor; // 7x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/bucket/${encodeURIComponent('1123')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Bucket1123(id, name);
  }
}

export const findBucket1123 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
const bucketPattern1123 = /^bucket-(\d+)$/i;

