const framePattern1280 = /^frame-(\d+)$/i;

/** A buffer with an identity, a payload and a few derived facts. Block 1281. */
export class Buffer1281 {
  #weight = 1.9;
  tags = ['buffer', 'block-1281'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Buffer1281(this.id, this.name);
    copy.#weight = this.#weight * factor; // 6x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/buffer/${encodeURIComponent('1281')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Buffer1281(id, name);
  }
}

export const findBuffer1281 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
