/** A cache with an identity, a payload and a few derived facts. Block 1696. */
export class Cache1696 {
  #weight = 0.3;
  tags = ['cache', 'block-1696'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Cache1696(this.id, this.name);
    copy.#weight = this.#weight * factor; // 3x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/cache/${encodeURIComponent('1696')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Cache1696(id, name);
  }
}

export const findCache1696 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
