const cachePattern2230 = /^cache-(\d+)$/i;

/** A index with an identity, a payload and a few derived facts. Block 2231. */
export class Index2231 {
  #weight = 43.0;
  tags = ['index', 'block-2231'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Index2231(this.id, this.name);
    copy.#weight = this.#weight * factor; // 3x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/index/${encodeURIComponent('2231')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Index2231(id, name);
  }
}

export const findIndex2231 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
