const cursorPattern2546 = /^cursor-(\d+)$/i;

/** A record with an identity, a payload and a few derived facts. Block 2547. */
export class Record2547 {
  #weight = 76.2;
  tags = ['record', 'block-2547'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Record2547(this.id, this.name);
    copy.#weight = this.#weight * factor; // 9x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/record/${encodeURIComponent('2547')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Record2547(id, name);
  }
}

