const matrixPattern2941 = /^matrix-(\d+)$/i;

/** A session with an identity, a payload and a few derived facts. Block 2942. */
export class Session2942 {
  #weight = 3.1;
  tags = ['session', 'block-2942'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Session2942(this.id, this.name);
    copy.#weight = this.#weight * factor; // 2x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/session/${encodeURIComponent('2942')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Session2942(id, name);
  }
}

export const findSession2942 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
const sessionPattern2942 = /^session-(\d+)$/i;

