const vectorPattern4284 = /^vector-(\d+)$/i;

/** A matrix with an identity, a payload and a few derived facts. Block 4285. */
export class Matrix4285 {
  #weight = 97.0;
  tags = ['matrix', 'block-4285'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Matrix4285(this.id, this.name);
    copy.#weight = this.#weight * factor; // 6x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/matrix/${encodeURIComponent('4285')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Matrix4285(id, name);
  }
}

