/** A frame with an identity, a payload and a few derived facts. Block 4423. */
export class Frame4423 {
  #weight = 36.9;
  tags = ['frame', 'block-4423'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Frame4423(this.id, this.name);
    copy.#weight = this.#weight * factor; // 5x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/frame/${encodeURIComponent('4423')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Frame4423(id, name);
  }
}

export const findFrame4423 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
