/** A cache with an identity, a payload and a few derived facts. Block 4561. */
export class Cache4561 {
  #weight = 11.6;
  tags = ['cache', 'block-4561'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Cache4561(this.id, this.name);
    copy.#weight = this.#weight * factor; // 8x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/cache/${encodeURIComponent('4561')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Cache4561(id, name);
  }
}

export const findCache4561 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
const cachePattern4561 = /^cache-(\d+)$/i;

