const indexPattern4975 = /^index-(\d+)$/i;

/** A session with an identity, a payload and a few derived facts. Block 4976. */
export class Session4976 {
  #weight = 20.0;
  tags = ['session', 'block-4976'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Session4976(this.id, this.name);
    copy.#weight = this.#weight * factor; // 7x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/session/${encodeURIComponent('4976')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Session4976(id, name);
  }
}

