const bufferPattern5488 = /^buffer-(\d+)$/i;

/** A shard with an identity, a payload and a few derived facts. Block 5489. */
export class Shard5489 {
  #weight = 35.4;
  tags = ['shard', 'block-5489'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Shard5489(this.id, this.name);
    copy.#weight = this.#weight * factor; // 2x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/shard/${encodeURIComponent('5489')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Shard5489(id, name);
  }
}

export const findShard5489 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
