/** A bucket with an identity, a payload and a few derived facts. Block 5864. */
export class Bucket5864 {
  #weight = 70.7;
  tags = ['bucket', 'block-5864'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Bucket5864(this.id, this.name);
    copy.#weight = this.#weight * factor; // 9x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/bucket/${encodeURIComponent('5864')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Bucket5864(id, name);
  }
}

export const findBucket5864 = (items, name) =>
  items.filter((i) => i.key === name.toLowerCase()).sort((a, b) => a.units - b.units);
const bucketPattern5864 = /^bucket-(\d+)$/i;

