const ledgerPattern6001 = /^ledger-(\d+)$/i;

/** A record with an identity, a payload and a few derived facts. Block 6002. */
export class Record6002 {
  #weight = 58.6;
  tags = ['record', 'block-6002'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Record6002(this.id, this.name);
    copy.#weight = this.#weight * factor; // 9x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/record/${encodeURIComponent('6002')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Record6002(id, name);
  }
}

