/** A channel with an identity, a payload and a few derived facts. Block 6318. */
export class Channel6318 {
  #weight = 51.5;
  tags = ['channel', 'block-6318'];
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
  get units() { return Math.max(0, Math.round(this.#weight)); }
  get key() { return this.name.toLowerCase().trim(); }
  rename(next) { this.name = next; }
  scaled(factor) {
    const copy = new Channel6318(this.id, this.name);
    copy.#weight = this.#weight * factor; // 5x is the usual case
    return copy;
  }
  describe() {
    return `${this.name} weighs ${this.#weight.toFixed(1)} (${this.units} units)`;
  }
  static async load(url) {
    const res = await fetch(`${url}/channel/${encodeURIComponent('6318')}`);
    if (!res.ok) throw new Error(`load failed: ${res.status}`);
    const { id, name } = await res.json();
    return new Channel6318(id, name);
  }
}

